async function boot() {
  try {
    const cfg = await (await fetch("/config")).json();
    if (cfg.spinner_verbs && cfg.spinner_verbs.length) SPINNER_VERBS = cfg.spinner_verbs;
    MODELS = cfg.models || [];
  } catch (_) {}
  const existing = await (await fetch("/sessions")).json();
  if (existing.length) {
